sys_script.script:
(function validateEWTGroupMembership(current) {
    // Skip if is_replacement is true - replacement bypasses ONLY group restriction
    var isReplacement = current.getValue('is_replacement');
    if (isReplacement == 'true' || isReplacement == '1' || isReplacement === true) {
        return;
    }

    var employeeId = current.getValue('employee');
    if (!employeeId) return; // No employee set, nothing to validate

    var rpId = current.getValue('resource_plan');
    if (!rpId) return; // No RP, can't validate group

    // Get the RP's assignment_group
    var rp = new GlideRecord('x_2316178_contin_0_res_plan');
    if (!rp.get(rpId)) return;

    var groupId = rp.getValue('assignment_group');
    if (!groupId) return; // No group on RP, allow

    // Check if employee is a member of the group
    var gm = new GlideRecord('sys_user_grmember');
    gm.addQuery('group', groupId);
    gm.addQuery('user', employeeId);
    gm.query();
    if (!gm.next()) {
        gs.addErrorMessage('Employee is not a member of the Resource Plan assignment group. Use "Is Replacement" to allow cross-group assignment.');
        current.setAbortAction(true);
    }
})(current);
